mkuse!{use crate :: pin :: Pin ;}
mkuse!{use crate :: sync :: atomic :: Ordering :: { Acquire , Relaxed , Release } ;}
mkuse!{use crate :: sync :: atomic :: { Atomic , AtomicUsize } ;}
mkuse!{use crate :: sys :: pal :: sync :: { Condvar , Mutex } ;}
mkuse!{use crate :: time :: Duration ;}
mkitem!{const EMPTY : usize = 0 ;}
mkitem!{const PARKED : usize = 1 ;}
mkitem!{const NOTIFIED : usize = 2 ;}
mkitem!{mkstruct!{pub struct Parker { state : Atomic < usize > , lock : Mutex , cvar : Condvar , }}}
mkitem!{mkimpl!{impl Parker { # [doc = " Constructs the UNIX parker in-place."] # [doc = ""] # [doc = " # Safety"] # [doc = " The constructed parker must never be moved."] pub unsafe fn new_in_place (parker : * mut Parker) { parker . write (Parker { state : AtomicUsize :: new (EMPTY) , lock : Mutex :: new () , cvar : Condvar :: new () , }) ; Pin :: new_unchecked (& mut (* parker) . cvar) . init () ; } fn lock (self : Pin < & Self >) -> Pin < & Mutex > { unsafe { self . map_unchecked (| p | & p . lock) } } fn cvar (self : Pin < & Self >) -> Pin < & Condvar > { unsafe { self . map_unchecked (| p | & p . cvar) } } pub unsafe fn park (self : Pin < & Self >) { if self . state . compare_exchange (NOTIFIED , EMPTY , Acquire , Relaxed) . is_ok () { return ; } self . lock () . lock () ; match self . state . compare_exchange (EMPTY , PARKED , Relaxed , Relaxed) { Ok (_) => { } Err (NOTIFIED) => { let old = self . state . swap (EMPTY , Acquire) ; self . lock () . unlock () ; assert_eq ! (old , NOTIFIED , "park state changed unexpectedly") ; return ; } Err (_) => { self . lock () . unlock () ; panic ! ("inconsistent park state") } } loop { self . cvar () . wait (self . lock ()) ; match self . state . compare_exchange (NOTIFIED , EMPTY , Acquire , Relaxed) { Ok (_) => break , Err (_) => { } } } self . lock () . unlock () ; } pub unsafe fn park_timeout (self : Pin < & Self > , dur : Duration) { if self . state . compare_exchange (NOTIFIED , EMPTY , Acquire , Relaxed) . is_ok () { return ; } self . lock () . lock () ; match self . state . compare_exchange (EMPTY , PARKED , Relaxed , Relaxed) { Ok (_) => { } Err (NOTIFIED) => { let old = self . state . swap (EMPTY , Acquire) ; self . lock () . unlock () ; assert_eq ! (old , NOTIFIED , "park state changed unexpectedly") ; return ; } Err (_) => { self . lock () . unlock () ; panic ! ("inconsistent park_timeout state") } } self . cvar () . wait_timeout (self . lock () , dur) ; match self . state . swap (EMPTY , Acquire) { NOTIFIED => self . lock () . unlock () , PARKED => self . lock () . unlock () , n => { self . lock () . unlock () ; panic ! ("inconsistent park_timeout state: {n}") } } } pub fn unpark (self : Pin < & Self >) { match self . state . swap (NOTIFIED , Release) { EMPTY => return , NOTIFIED => return , PARKED => { } _ => panic ! ("inconsistent state in unpark") , } unsafe { self . lock () . lock () ; self . lock () . unlock () ; self . cvar () . notify_one () ; } } }}}